import * as React from "react";
import * as AvatarPrimitive from "@radix-ui/react-avatar";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * figma: Avatar (Size = sm 24 | default 32 | lg 40), AvatarBadge
 * (Type = Icon | Status, Size = xs 8 | default 10 | lg 12) and AvatarGroup
 * (Dir = LTR | RTL, -8px overlap).
 */
const avatarVariants = cva("relative flex shrink-0 overflow-hidden rounded-full", {
  variants: {
    size: { sm: "size-6", default: "size-8", lg: "size-10" },
  },
  defaultVariants: { size: "default" },
});

function Avatar({
  className,
  size,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Root> & VariantProps<typeof avatarVariants>) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      className={cn(avatarVariants({ size }), className)}
      {...props}
    />
  );
}

function AvatarImage({ className, ...props }: React.ComponentProps<typeof AvatarPrimitive.Image>) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      className={cn("aspect-square size-full object-cover", className)}
      {...props}
    />
  );
}

function AvatarFallback({
  className,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Fallback>) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      className={cn(
        "flex size-full items-center justify-center rounded-full bg-muted text-xs font-medium",
        className
      )}
      {...props}
    />
  );
}

const avatarBadgeVariants = cva(
  "absolute end-0 bottom-0 flex items-center justify-center rounded-full border-2 border-background",
  {
    variants: {
      variant: {
        icon: "bg-primary text-primary-foreground [&_svg]:size-2",
        status: "bg-primary",
      },
      size: { xs: "size-2", default: "size-2.5", lg: "size-3" },
    },
    defaultVariants: { variant: "status", size: "default" },
  }
);

function AvatarBadge({
  className,
  variant,
  size,
  ...props
}: React.ComponentProps<"span"> & VariantProps<typeof avatarBadgeVariants>) {
  return (
    <span
      data-slot="avatar-badge"
      className={cn(avatarBadgeVariants({ variant, size }), className)}
      {...props}
    />
  );
}

/** figma: AvatarGroup — a -8px overlapping stack with a ring in `background`. */
function AvatarGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="avatar-group"
      className={cn(
        "flex items-center -space-x-2 [&>[data-slot=avatar]]:ring-2 [&>[data-slot=avatar]]:ring-background",
        className
      )}
      {...props}
    />
  );
}

/**
 * A trailing "+N" chip on an AvatarGroup. An icon can be used instead of a
 * count. Sized to match the group's avatars.
 */
function AvatarGroupCount({
  className,
  size,
  ...props
}: React.ComponentProps<"span"> & VariantProps<typeof avatarVariants>) {
  return (
    <span
      data-slot="avatar-group-count"
      className={cn(
        avatarVariants({ size }),
        "items-center justify-center bg-muted text-xs font-medium text-muted-foreground",
        "ring-2 ring-background [&_svg:not([class*='size-'])]:size-3.5",
        className
      )}
      {...props}
    />
  );
}

export {
  Avatar,
  AvatarImage,
  AvatarFallback,
  AvatarBadge,
  AvatarGroup,
  AvatarGroupCount,
  avatarVariants,
};
